import json, sys
from urllib import request, parse, error
BASE = 'http://127.0.0.1:8125'

def get(path):
    try:
        with request.urlopen(BASE + path, timeout=30) as r:
            raw = r.read()
            if not 200 <= r.status < 300:
                raise RuntimeError(f'GET {path} failed with HTTP {r.status}')
    except error.HTTPError as e:
        raise RuntimeError(f'GET {path} failed with HTTP {e.code}: {e.read().decode("utf-8", "replace")}') from e
    except error.URLError as e:
        raise RuntimeError(f'GET {path} request failed: {e.reason}') from e
    try:
        return json.loads(raw)
    except (json.JSONDecodeError, UnicodeDecodeError) as e:
        raise RuntimeError(f'GET {path} returned invalid JSON: {e}') from e

try:
    meta = get('/batches/last')
    last_seq = meta.get('last_seq') if isinstance(meta, dict) else None
    if isinstance(last_seq, bool) or not isinstance(last_seq, int):
        raise RuntimeError('GET /batches/last JSON does not contain integer last_seq')
    page = get('/orders?after=' + parse.quote(str(last_seq), safe=''))
    orders = page.get('orders') if isinstance(page, dict) else page
    if not isinstance(orders, list):
        raise RuntimeError('GET /orders did not return an orders list')
    if not orders:
        sys.exit(0)

    seqs, total_units, total_revenue = [], 0, 0
    by_region = {}
    for i, o in enumerate(orders):
        if not isinstance(o, dict):
            raise RuntimeError(f'order {i} is not an object')
        seq, units, region = o.get('seq'), o.get('units'), o.get('region')
        # The current local API names its cent-denominated price field unit_price_minor.
        price = o.get('unit_price_cents', o.get('unit_price_minor'))
        for name, value in [('seq', seq), ('units', units), ('unit price', price)]:
            if isinstance(value, bool) or not isinstance(value, int):
                raise RuntimeError(f'order {i} has invalid {name}')
        if not isinstance(region, str):
            raise RuntimeError(f'order {i} has invalid region')
        revenue = units * price
        seqs.append(seq)
        total_units += units
        total_revenue += revenue
        by_region[region] = by_region.get(region, 0) + revenue

    payload = {
        'batch_start_seq': min(seqs),
        'batch_end_seq': max(seqs),
        'order_count': len(orders),
        'total_units': total_units,
        'total_revenue_cents': total_revenue,
        'revenue_by_region_cents': by_region,
    }
    req = request.Request(BASE + '/batches', data=json.dumps(payload, separators=(',', ':')).encode(),
                          headers={'Content-Type': 'application/json'}, method='POST')
    try:
        with request.urlopen(req, timeout=30) as r:
            raw = r.read()
            if not 200 <= r.status < 300:
                raise RuntimeError(f'POST /batches failed with HTTP {r.status}: {raw.decode("utf-8", "replace")}')
    except error.HTTPError as e:
        raise RuntimeError(f'POST /batches failed with HTTP {e.code}: {e.read().decode("utf-8", "replace")}') from e
    except error.URLError as e:
        raise RuntimeError(f'POST /batches request failed: {e.reason}') from e
except Exception as e:
    print(f'Order batch processing failed: {e}', file=sys.stderr)
    sys.exit(1)
